import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/ganesha/festivals/ganesha-chaturthi/',[('','Gaṇeśa Caturthī','The Birthday of the Remover of Obstacles')],'red','Gaṇeśa Caturthī','Lord','Gaṇeśa Caturthī')
PG.CFG.update(backurl='/ganesha/festivals/',backname='Gaṇeśa festivals')
PG.OUT='outd/ganesha-chaturthi/'
i=0
GA=lambda s=1: g(0,0,s,ganesha())
GS=lambda: ganesha(seat=False)
PAR=lambda: devi(sari='#2a9d6f',items=('lotus',))
def jewel(): return '<path d="M-10 0 l-6 -10 l16 -14 l16 14 l-6 10z" fill="#c0392b"/><path d="M-10 0 h20" stroke="#e0a800"/>'
def headless(): return '<path d="M-12 0 l3 -32 h18 l3 32z" fill="#e8703a"/>'
def elephant_head(): return '<circle cy="-40" r="14" fill="#9a9aaa"/><path d="M-6 -30 q-4 20 6 30" stroke="#9a9aaa" stroke-width="7" fill="none"/><ellipse cx="-16" cy="-40" rx="8" ry="12" fill="#8a8a9a"/><ellipse cx="16" cy="-40" rx="8" ry="12" fill="#8a8a9a"/>'
def pandal(): return '<path d="M-70 0 v-80 M70 0 v-80" stroke="#6a4a2a" stroke-width="5"/><path d="M-80 -80 l80 -30 l80 30z" fill="#c0392b"/>'+''.join(f'<path d="M{x} -80 q8 10 16 0" fill="none" stroke="#e0a800" stroke-width="3"/>' for x in range(-76,76,16))
def tilak(): return god('#f4f1ea')+'<path d="M-10 -52 q10 -10 20 0" fill="#c0392b"/>'
def leaves21(): return ''.join(g(-60+k*20,0,.5,leaf(['#2f7a3a','#3a9a4a','#5a8a3a'][k%3])) for k in range(7))
COV=covart('A clay Gaṇeśa on a decorated seat with modakas, dūrvā grass and lamps, a crescent moon hidden behind a cloud',f'<rect width="440" height="196" fill="#f6e3e1"/>'+'<rect y="160" width="440" height="36" fill="#e9c9c3"/>'+g(220,170,1.6,ganesha())+g(220,186,.9,mouse())+g(110,186,1.5,plate())+g(100,174,1,modaka())+g(120,176,1,modaka())+g(330,186,1.6,lamp())+g(380,186,1.4,durva())+g(400,40,.8,moon())+'<path d="M370 50 q20 -24 50 -4 q20 -6 24 10 h-74z" fill="#cfd8e6"/>')
pp=[foreword(i,['On the fourth day of the bright fortnight of Bhādrapada, India brings home a clay god with an elephant’s head. For a day and a half, three, five, seven or ten days he is fed modakas, sung to and worshipped, and then carried to water with drums and the cry “<b>Gaṇapati bappā moryā!</b>” This is <b>Gaṇeśa Caturthī</b>, the most joyful public festival of the year.','In Karnataka it is the second day of <b>Gaurī-Gaṇeśa habba</b>: the mother comes first, the son the next day (read our '+L('/ganesha/festivals/gauri-ganesha-habba/','Gaurī-Gaṇeśa')+' article). This article tells Gaṇeśa’s birth as the Śiva Purāṇa tells it, the curse of the moon and Kṛṣṇa’s jewel, the twenty-one leaves and the modaka, gives three verses, and follows the festival from home to Tilak’s Pune and the pandals of Bengaluru, ending at the water.'],[('z','Is it really his birthday?'),('b','In popular belief, yes, Zappy. Maharashtra keeps another in Māgha. Gaṇeśa doesn’t mind two birthdays.')]),
 glance([('Name','Gaṇeśa Caturthī; Vināyaka Caturthī; Gaṇeśa habba (Karnataka), Gaṇeśotsav (Maharashtra)'),('When','Bhādrapada Śukla Caturthī; August–September'),('Length','1½ to 10 days; the ten-day festival ends on Ananta Caturdaśī'),('At home','A clay image welcomed, worshipped with 21 leaves, 21 dūrvā, 21 modakas; then immersed'),('Avoid','Looking at the moon that night'),('Texts','Śiva Purāṇa (birth); Bhāgavata 10.56–57 (Syamantaka); Mudgala and Gaṇeśa Purāṇas'),('Public festival','Popularised by Bāḷ Gaṅgādhar Tilak in Pune from 1893')],svg(560,140,'Gaṇeśa under a pandal with modakas',f'<rect width="560" height="140" fill="#f6e3e1"/>'+g(280,138,.9,pandal())+g(280,130,1.1,ganesha())+g(150,130,1.3,plate())+g(140,120,1,modaka())+g(420,130,1.3,lamp()))),
 reading('date','THE FOURTH OF BHĀDRAPADA','Caturthī and its moon',svg(560,160,'The moon on the fourth day of the bright fortnight, a thin crescent, behind a cloud',f'<rect width="560" height="160" fill="#20243a"/>'+'<path d="M260 50 a28 28 0 1 0 30 50 a22 22 0 1 1 -30 -50z" fill="#fff8d0" stroke="none"/>'+'<path d="M230 70 q30 -30 80 -10 q40 -6 40 20 h-130z" fill="#5a6a8a"/>'+lab(280,140,'Śukla Caturthī: a young moon').replace('#111','#fff8d0')),['<b>The day.</b> Every lunar month has two Caturthīs: the dark one is '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī')+', the bright one Vināyaka Caturthī. The bright Caturthī of Bhādrapada, in the rains, is the great festival.','<b>Midday.</b> Gaṇeśa’s worship is done at midday (<i>madhyāhna</i>), when he is said to have been born; almanacs give the window.','<b>The moon.</b> That night, people avoid looking at the moon. The story behind it, and Kṛṣṇa’s brush with it, is told a few pages on.','<b>How long.</b> Families keep him for one and a half, three, five, seven or ten days, by custom. Public pandals usually keep ten, ending on <b>Ananta Caturdaśī</b> with the great immersions.'],[('z','Why avoid the moon?'),('b','A story about laughing at someone who fell, Zappy. Wait for it.')],'The bright fourth <b>of the rains</b>.'),
 story('birth','THE BOY AT THE DOOR','How Gaṇeśa got his head',strip('Three panels: Pārvatī shaping a boy from turmeric paste; the boy guarding the door against Śiva; Śiva placing an elephant’s head on the boy',[panel([(PAR(),1),(child(),.8)],'#fff3cf',150),panel([(child(),.9),(shiva(),.9)],'#e3eaf3',150),panel([(shiva(),.8),(GS(),.8)],'#f6e3e1',150)],['made from turmeric','the guard','the new head']),'Śiva Purāṇa, Rudra Saṃhitā, Kumāra Khaṇḍa (chs. 13–18 in common editions). Other Purāṇas tell it differently.',['<b>Pārvatī</b>, wanting a guard of her own, took the turmeric paste from her body as she bathed and shaped from it a handsome boy, breathed life into him, and set him at her door: let no one in.','<b>Śiva</b> came home. The boy, who had never seen him, barred the way. Śiva’s attendants, the gaṇas, fought him and were beaten back; at last Śiva himself cut off the boy’s head.','Pārvatī, grief-stricken and furious, threatened to destroy the worlds with her Śaktis. The gods begged Śiva to restore the child.','Śiva sent his gaṇas north to bring the head of the first creature they met: an elephant. He set it on the boy’s body and brought him back to life.','He made the boy chief of the gaṇas, <b>Gaṇapati</b>, and decreed that he would be worshipped first, before every other god, in every undertaking: <b>Vighneśvara</b>, lord of obstacles.'],[('z','Śiva didn’t know his own son?'),('b','He’d never met him, Zappy. The story is about a father learning, the hard way, and making it right.')],'A head lost, <b>a god first</b>.'),
 verse('v-vakra','Vakratuṇḍa mahākāya','The first verse of every beginning',['vakratuṇḍa mahākāya sūryakoṭisamaprabha','nirvighnaṃ kuru me deva sarvakāryeṣu sarvadā'],svg(200,150,'Gaṇeśa with a curved trunk shining like many suns',f'<rect width="200" height="150" fill="#f6e3e1"/>'+''.join(f'<path d="M100 75 l{60*__import__("math").cos(k*0.52):.1f} {60*__import__("math").sin(k*0.52):.1f}" stroke="#ffd60a" stroke-width="2"/>' for k in range(12))+g(100,140,1.2,ganesha())),'O god with the curved trunk and the great body, radiant as a crore of suns: make all my work free of obstacles, always.',[('vakra-tuṇḍa','curved trunk'),('mahā-kāya','great body'),('sūrya-koṭi','a crore of suns'),('samaprabha','equal in radiance'),('nirvighnam','free of obstacles'),('sarva-kāryeṣu','in all undertakings')],'<b>Why he comes first.</b> Śiva’s decree, that Gaṇeśa be worshipped first, is why this verse opens exams, weddings, journeys and every pūjā in Karnataka homes. On Caturthī it is said before the image is even unwrapped.',k='<b>No obstacles</b>, always.',note='Text as on our '+L('/ganesha/hymns/daily-slokas/','Gaṇeśa daily ślokas')+' page.'),
 story('moon','THE MOON LAUGHED','Why we don’t look up that night',strip('Three panels: Gaṇeśa falling from his mouse with modakas spilling; the moon laughing; Gaṇeśa cursing the moon',[panel([(GS(),.8),(mouse(),.8),(modaka(),.7)],'#20243a',150),panel([(moon(),1.6)],'#20243a',150),panel([(GS(),.9),(moon(),.8)],'#3a3a5a',150)],['the tumble','the laugh','the curse']),'A widely told story, with versions in the Purāṇas; read the long version in our '+L('/ganesha/stories/moon-curse/','moon’s curse')+' story.',['On his birthday Gaṇeśa ate all the modakas the world offered him, and rode home at night on his little mouse.','A snake crossed the path; the mouse stumbled, and Gaṇeśa tumbled, his belly bursting and the modakas rolling out. Unruffled, he stuffed them back and tied his belly shut with the snake.','The <b>Moon</b>, proud of his beauty, burst out laughing at the pot-bellied god in the dust.','Gaṇeśa cursed him: no one should look at him, and whoever did would be falsely accused (<b>mithyā-doṣa</b>).','The gods pleaded; Gaṇeśa softened the curse to one night, his own Caturthī in Bhādrapada. So that night, people keep their eyes down; and whoever sees the moon by accident is told to hear the next story.'],[('z','The moon laughed at him?'),('b','At someone who fell, Zappy. That’s the real lesson: don’t mock anyone’s body.')],'Never laugh <b>at a fall</b>.'),
 story('syamantaka','KṚṢṆA AND THE JEWEL','The cure for seeing the moon',strip('Three panels: a shining jewel; Kṛṣṇa accused of stealing it; Kṛṣṇa returning the jewel after fighting Jāmbavān',[panel([(jewel(),2)],'#fff3cf',150),panel([(god('#2a5aa8'),.9),(person('#c0392b'),.8),(person('#7a3fa0'),.8)],'#fde4e4',150),panel([(god('#2a5aa8'),.9),(beast('bear','#3a2a1a') if False else '<ellipse cy="-26" rx="16" ry="22" fill="#3a2a1a"/><circle cy="-52" r="10" fill="#3a2a1a"/>',.9),(jewel(),.8)],'#e3f5e9',150)],['Syamantaka','false blame','the jewel returned']),'Bhāgavata Purāṇa 10.56–57.',['Satrājit of Dvārakā received from the Sun the shining jewel <b>Syamantaka</b>, which produced gold every day. Kṛṣṇa suggested he give it to the king for the good of all; Satrājit refused.','His brother Prasena wore it hunting and was killed by a lion; the bear-king <b>Jāmbavān</b> killed the lion and took the jewel to his cave. Dvārakā whispered that Kṛṣṇa had killed Prasena for it: false blame. Tradition says Kṛṣṇa had glimpsed the moon on Caturthī.','To clear his name, Kṛṣṇa followed the tracks into the cave and fought Jāmbavān for twenty-eight days, until the old bear recognised him as Rāma, whom he had served, and gave him the jewel and his daughter Jāmbavatī.','Kṛṣṇa returned the jewel to Satrājit before the whole city; the ashamed Satrājit gave him his daughter Satyabhāmā.','So the custom: whoever sees the moon on Gaṇeśa Caturthī should hear or read the Syamantaka story, and the blame passes.'],[('z','Even Kṛṣṇa was blamed?'),('b','And he cleared his name by finding the truth, Zappy. That’s the remedy, story and all.')],'Clear your name <b>with the truth</b>.'),
 reading('worship','WELCOMING HIM HOME','The clay image and the pūjā',svg(560,170,'A family carrying a covered clay Gaṇeśa home, then seated before him with offerings',f'<rect width="560" height="170" fill="#f6e3e1"/>'+'<rect y="140" width="560" height="30" fill="#e9c9c3"/>'+g(130,145,1,person('#2a5aa8'))+g(160,100,.8,ganesha())+'<path d="M140 70 h44 v20 h-44z" fill="#c0392b" opacity=".6"/>'+g(380,145,1.3,ganesha())+g(470,148,1.2,plate())+g(470,136,1,modaka())+g(300,150,1.2,lamp())),['<b>Bringing him home.</b> The clay image is bought or made at home and carried in with its face covered, to be unveiled before the shrine. Many families bring him the day before or on the morning itself.','<b>Prāṇa-pratiṣṭhā.</b> At midday the image is installed with a short rite inviting the deity into it, and worshipped with the sixteen services: water, cloth, sacred thread, sandal, flowers, incense, lamp, food.','<b>Twenty-one of everything.</b> The special worship is with <b>21 kinds of leaves</b> (ekaviṃśati patra), <b>21 blades of dūrvā grass</b> in each offering, and <b>21 modakas</b>. Each leaf is offered with one of his names.','<b>Songs.</b> The Gaṇeśa Pañcaratna, the Atharvaśīrṣa, the Saṅkaṭanāśana stotra, Purandara Dāsa’s “Gajavadana bēḍuve”, and in Maharashtra the āratī “Sukhakartā Duḥkhahartā” by Samartha Rāmdās.'],[('z','Why twenty-one?'),('b','Many explanations, Zappy: 5 senses of action, 5 of knowledge, 5 breaths, 5 elements and the mind. Or simply: plenty, offered with love.')],'A guest <b>with an elephant’s head</b>.'),
 cards('offerings','MODAKA, DŪRVĀ AND THE 21 LEAVES','What he loves, and why',fig_row('Modakas, dūrvā grass, leaves and a plate of laddus',[(modaka(),2),(durva(),2),(leaves21(),1),(laddu(),1.8)],['modaka','dūrvā','21 leaves','uṇḍe'],gy=150),[('🥟','Modaka','Steamed dumplings of rice flour filled with coconut and jaggery (<i>kaḍubu</i> in Kannada). He holds one in his hand: it stands, many teachers say, for the sweetness of knowledge. (Interpretation.)'),('🌿','Dūrvā','Three- or five-bladed tufts of dūrvā grass, offered in 21s. A popular story says Gaṇeśa swallowed a fire-demon, Analāsura, and only dūrvā cooled his burning stomach.'),('🍃','The 21 leaves','Śamī, bilva, dūrvā, tulasī, arka, jasmine, bhṛṅgarāja and others, each with a name of Gaṇeśa; many are medicinal plants of the rainy season.'),('🌸','Avoid','Tulasī is, by one tradition, offered to Gaṇeśa only on this day; red flowers, especially hibiscus, are his favourite.')],[('z','Why does he eat so much?'),('b','Lambodara, the big-bellied, holds the whole universe in his belly, Zappy. The modakas are a small part of it.')],'Sweet, green <b>and twenty-one</b>.'),
 verse('v-atharva','Gaṇapati Atharvaśīrṣa, verse 1','You alone are the truth',['namaste gaṇapataye','tvam eva pratyakṣaṃ tattvam asi','tvam eva kevalaṃ kartāsi','tvam eva kevalaṃ dhartāsi','tvam eva kevalaṃ hartāsi','tvam eva sarvaṃ khalv idaṃ brahmāsi'],svg(200,150,'Gaṇeśa inside a circle of light',f'<rect width="200" height="150" fill="#f6e3e1"/>'+'<circle cx="100" cy="80" r="60" fill="#fff8d0"/>'+g(100,140,1.2,ganesha())),'Salutations to you, Gaṇapati. You alone are the visible truth; you alone are the creator, the sustainer, the destroyer; you are all this, indeed Brahman.',[('pratyakṣam','directly visible'),('tattvam','the truth, the principle'),('kartā','creator'),('dhartā','sustainer'),('hartā','destroyer'),('brahma','the Absolute')],'<b>More than the remover of obstacles.</b> The Gaṇapati Atharvaśīrṣa, an Upaniṣad of the Gāṇapatya tradition, gives Gaṇeśa the highest place: he is creator, sustainer and destroyer, the Absolute itself. Many Karnataka and Maharashtrian families chant it 21 times on Caturthī.',k='He is <b>all of this</b>.',note='Text as on our '+L('/ganesha/hymns/atharvashirsha-1/','Atharvaśīrṣa, part 1')+' page.'),
 reading('tilak','FROM HOME TO STREET','Tilak’s public festival',svg(560,160,'A leader in a turban addressing a crowd before a large Gaṇeśa under a pandal, 1890s',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="130" width="560" height="30" fill="#e9c9c3"/>'+g(380,140,1.1,pandal())+g(380,130,1.3,ganesha())+g(170,140,1.2,tilak())+''.join(g(x,150,.7,person(c)) for x,c in [(60,'#2a5aa8'),(100,'#c0392b'),(240,'#2a9d6f')])),['<b>Private, then public.</b> For centuries Gaṇeśa Caturthī was mainly a household festival, with grand celebrations at the Peshwas’ court in Pune.','<b>Tilak.</b> In 1893 the nationalist leader <b>Bāḷ Gaṅgādhar Tilak</b> promoted it as a public festival (sārvajanik Gaṇeśotsav), with large images in public pandals, ten days of lectures, music and drama, and a collective procession to the water. Under colonial rule it gave people a lawful way to gather in numbers.','<b>Spread.</b> The public festival spread across Maharashtra and then the country. Bengaluru’s pandals, the Basavanagudi festival with its month of concerts, and every town’s “Gaṇeśa kūrisuvudu” owe something to it.','<b>Today.</b> Mumbai’s Lālbāugcā Rājā, Pune’s Dagaḍuśeṭh Halvāī and Kasbā Gaṇapati, Hyderabad’s Khairatabad Gaṇeśa draw millions; in Karnataka almost every street has its own.'],[('z','A festival as politics?'),('b','As gathering, Zappy. People who pray together learn to stand together. Tilak knew it.')],'From the <b>shrine to the street</b>.'),
 reading('karnataka','GAṆEŚA HABBA IN KARNATAKA','The son who comes for his mother',svg(560,160,'Gaurī and Gaṇeśa seated side by side in a home shrine, with a plate of kaḍubu',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="135" width="560" height="25" fill="#e9c9c3"/>'+g(220,140,1.1,PAR())+g(320,140,1.2,ganesha())+g(440,140,1.2,plate())+g(440,130,1,modaka())),['<b>Gaurī first.</b> In Karnataka the festival is two days: Gaurī (Pārvatī) is welcomed on the third, as a married daughter visiting her parents; Gaṇeśa arrives on the fourth, the story goes, to take her home. Read our '+L('/ganesha/festivals/gauri-ganesha-habba/','Gaurī-Gaṇeśa')+' article.','<b>The kitchen.</b> Kaḍubu (modakas), kariganḍu, uṇḍe, pañcakajjāya (a mix of five: gram, coconut, sesame, jaggery and ghee), cakkuli and a festive meal.','<b>The streets.</b> Neighbourhood youth groups set up pandals with images of every size; orchestras, plays and contests run for days; the immersion processions with drums and dances are the climax.','<b>Bengaluru.</b> The city’s Basavanagudi and Malleshwaram pandals and the long-running music festivals of the season are famous; Mysuru’s, Hubbaḷḷi-Dhāravāḍ’s and Belagāvi’s public festivals are among the biggest in the state.'],[('z','He comes to take his mother home?'),('b','That’s the Karnataka telling, Zappy. A son fetching his mother from her parents’ house. It’s why the festival feels like family.')],'Mother, then son, <b>then the street</b>.'),
 verse('v-sankata','Saṅkaṭanāśana Stotra, verses 1–2','Twelve names that remove distress',['praṇamya śirasā devaṃ gaurīputraṃ vināyakam','bhaktāvāsaṃ smaren nityam āyuṣkāmārthasiddhaye','prathamaṃ vakratuṇḍaṃ ca ekadantaṃ dvitīyakam','tṛtīyaṃ kṛṣṇapiṅgākṣaṃ gajavaktraṃ caturthakam'],svg(200,150,'Gaṇeśa with twelve small lamps around him',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(100,140,1.1,ganesha())+''.join(g(100+75*__import__("math").cos(3.3+k*0.27),140+90*__import__("math").sin(3.3+k*0.27),.45,lamp()) for k in range(12))),'Bowing my head to the god Vināyaka, son of Gaurī, dwelling place of devotees, one should remember him always, for long life, desires and wealth. First, Vakratuṇḍa; second, Ekadanta; third, Kṛṣṇapiṅgākṣa; fourth, Gajavaktra…',[('gaurī-putram','son of Gaurī'),('bhakta-āvāsam','home of devotees'),('vakratuṇḍam','curved trunk'),('ekadantam','one tusk'),('kṛṣṇapiṅgākṣam','dark-and-tawny-eyed'),('gajavaktram','elephant-faced')],'<b>Twelve names.</b> This Nārada Purāṇa stotra lists twelve names of Gaṇeśa, the same names that give each month’s Saṅkaṣṭī its form. Chanting the twelve is the shortest Caturthī worship of all. Our '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī series')+' takes them one by one.',k='Twelve names <b>against distress</b>.',note='Text as on our '+L('/ganesha/hymns/sankatanashana-stotra/','Saṅkaṭanāśana Stotra')+' page.'),
 reading('visarjana','VISARJANA','Goodbye to the water',svg(560,170,'A procession with drums carrying Gaṇeśa to a lake, the image lowered into the water',f'<rect width="560" height="170" fill="#f6e3e1"/>'+'<path d="M300 130 q130 -10 260 0 v40 h-260z" fill="#8fb8de"/>'+g(430,140,1,ganesha())+''.join(g(x,150,.8,person(c)) for x,c in [(60,'#2a5aa8'),(110,'#c0392b'),(160,'#2a9d6f'),(210,'#e0a800')])+g(260,140,.9,'<ellipse rx="16" ry="12" cy="-16" fill="#8a5a3a"/>')),['<b>The farewell.</b> On the chosen day, after a final ārati and offerings, the image is lifted with a last “come again soon” (<i>pudhcyā varṣī lavkar yā</i>, “come early next year”, in Marathi) and carried to a lake, river, sea or tank, and immersed.','<b>Why immerse?</b> The clay returns to the earth and water it was made from. Many teachers read it as a lesson in non-attachment: we receive God in a form, love him, and let the form go. (Interpretation.)','<b>The processions.</b> In towns the procession with drums (ḍhol-tāśā), dancing and coloured powder can last all night, especially on Ananta Caturdaśī.','<b>Gaurī’s farewell.</b> In Karnataka homes Gaurī and Gaṇeśa often leave together, the mother going home with her son.'],[('z','Isn’t it sad to put him in the water?'),('b','A little, Zappy. That’s why we shout “come back next year!”')],'Form returned to <b>clay and water</b>.'),
 cards('green','A GREENER FESTIVAL','Clay, colour and the lakes',fig_row('A plain clay Gaṇeśa, a bucket of water, a tree and a lake',[(ganesha(c='#b5651d',dhoti='#c98a5a',crown='#c98a5a'),1),(pot('#8fb8de'),1.4),(tree(),.8),(river(144,40),1)],['clay','home immersion','seed Gaṇeśa','clean lakes'],gy=150),[('🏺','Clay, not plaster','Plaster of Paris and chemical paints pollute lakes and do not dissolve. Karnataka and other states have banned or restricted PoP idols; plain clay (<i>shāḍu</i>) images are the traditional ones.'),('🪣','Immerse at home','Many families now immerse a small clay image in a bucket at home and pour the water and clay on a garden.'),('🌱','Seed Gaṇeśa','Some clay images carry seeds inside; dissolved in a pot, they grow into a plant.'),('🏞️','Tanks','Cities set up special immersion tanks so that lakes stay clean; Bengaluru’s lakes are the reason the rules came.')],[('z','A Gaṇeśa that grows into a plant?'),('b','A lovely idea, Zappy. Clay to clay, life to life.')],'Love Gaṇeśa, <b>love the lake</b>.'),
 reading('meaning','WHAT GAṆEŚA MEANS','The god of beginnings',svg(560,150,'Gaṇeśa at a doorway with a broken tusk and a pen, writing',f'<rect width="560" height="150" fill="#f6e3e1"/>'+'<rect x="200" y="10" width="160" height="140" fill="#c9a06a"/><rect x="230" y="30" width="100" height="120" fill="#fff8e7"/>'+g(280,145,1.2,ganesha())+g(420,120,1.4,book())),['<b>First.</b> He is worshipped first because every beginning needs a doorkeeper: the one who removes obstacles, and also places them when we need to stop. (Interpretation.)','<b>The head.</b> The elephant head is read as wisdom: big ears to listen, small eyes to focus, a trunk that can lift a tree or a needle. The broken tusk, in one story, became the pen with which he wrote down the Mahābhārata as Vyāsa dictated. See our '+L('/ganesha/stories/broken-tusk/','broken tusk')+' story.','<b>The mouse.</b> The huge god rides the tiny mouse: the restless mind, or desire, mastered and made a vehicle.','<b>The people’s god.</b> No god is as loved by children, as shared across castes and regions, or as easy to make with your own hands from a lump of clay.'],[('z','If I could do one thing for Gaṇeśa Caturthī?'),('b','Make a little clay Gaṇeśa with your own hands, Zappy, say “vakratuṇḍa mahākāya” and start something you’ve been putting off.')],'The doorkeeper of <b>every beginning</b>.'),
 end(i,['<b>When.</b> Bhādrapada Śukla Caturthī, at midday.','<b>Birth.</b> Pārvatī’s turmeric boy, Śiva’s fury, the elephant head, first worship.','<b>Moon.</b> The moon laughed; Kṛṣṇa’s Syamantaka clears the blame.','<b>Worship.</b> 21 leaves, 21 dūrvā, 21 modakas; Vakratuṇḍa, Atharvaśīrṣa, Saṅkaṭanāśana.','<b>Street.</b> Tilak’s 1893 festival, the pandals, visarjana, clay not plaster.'],'Previous: '+L('/ganesha/festivals/gauri-ganesha-habba/','Gaurī-Gaṇeśa habba')+'. Next: '+L('/ganesha/festivals/sankashti-chaturthi/','Saṅkaṣṭī Caturthī')+'.','Gaṇeśa Caturthī: the remover of obstacles'),
 sources([('Texts:','Śiva Purāṇa, Rudra Saṃhitā, Kumāra Khaṇḍa (birth); Bhāgavata Purāṇa 10.56–57 (Syamantaka); Gaṇapati Atharvaśīrṣa, Vakratuṇḍa and Saṅkaṭanāśana (Nārada Purāṇa) texts from our own pages.'),('Festival and history:','Wikipedia, “Ganesh Chaturthi” (date, duration, Tilak 1893, visarjana, environmental rules); Karnataka customs as summarised in our Gaurī-Gaṇeśa guide.')],'other Purāṇic birth stories (Brahmavaivarta: Śani’s glance; tellings differ); the moon-curse story (several versions); the Analāsura dūrvā story (popular); the list of 21 leaves (varies); explanations of 21 (traditional and popular).','Interpretations are marked as such.')]
build(i,'BHĀDRAPADA CATURTHĪ · MODAKA · VISARJANA',COV,'Modakas, dūrvā and a hidden moon','The <b>day</b> and its moon, Gaṇeśa’s <b>birth</b>, the moon’s curse and Kṛṣṇa’s jewel, the <b>21 offerings</b>, three verses, and the festival from home to <b>Tilak’s street</b> and the water.','Gaṇeśa Caturthī explained: Bhādrapada Śukla Caturthī, Pārvatī’s turmeric boy and the elephant head (Śiva Purāṇa), the moon’s curse and the Syamantaka jewel, Vakratuṇḍa, Atharvaśīrṣa and Saṅkaṭanāśana verses, 21 leaves, dūrvā and modaka, Tilak’s public festival of 1893, Karnataka’s Gaṇeśa habba, visarjana and clay idols.',pp)
